  "config": {
    "commitizen": {
      "path": "./node_modules/cz-conventional-changelog"
    }
  },
  "lint-staged": {
    "**/*.py": [
      "uv run ruff format",
      "uv run ruff check --fix"
    ],
    "flowsint-app/**/*.{ts,tsx,js,jsx}": [
      "prettier --write"
    ]
  },
